"""Rounded intersection mesh and one live mouth per actual Section member.

A divided connector retains the established full-envelope crown with a flat
separator plateau.  Its two mouth records refer to the two authored member
centerlines, not an invented shared centerline.  Each member receives one
half-crown, with the plateau at its inner edge and zero height at its outer
edge.  Section sweeps own all approach pavement and separator strips.
"""
import bpy


NAME = 'Prochitecture Streets / Profiled intersection mouths v1'


def build(*, coupled=False, adaptive_half_profiles=False):
    name = NAME if not coupled else 'Prochitecture Streets / Coupled intersection mouths v2'
    if adaptive_half_profiles:
        if not coupled:raise ValueError('Adaptive half profiles require coupled member mouths')
        name='Prochitecture Streets / Coupled intersection mouths v3'
    existing = bpy.data.node_groups.get(name)
    if existing is not None:
        return existing

    from .runtime import ensure_kernel,solver_modules
    solver_modules()
    from ..kernel.backend_runtime import Graph, V, choose, named, rm
    from ..kernel import prepare
    from ..kernel import backend
    from ..kernel import geometry_guard
    from ..kernel import oblique
    from ..kernel import inputs as contract
    # Saved assemblies need not retain the unused top-level Section modifier.
    # Its absence does not mean that the shared preparation/backend are absent.
    # Rebuilding that modifier would replace helpers already used by the scene.
    if any(key not in bpy.data.node_groups for key in (prepare.NAME,backend.NAME)):
        ensure_kernel()

    g = Graph(name)
    g.socket('Carrier', 'NodeSocketGeometry')
    radial = g.socket('Radial Samples', 'NodeSocketInt', default=8)
    radial.min_value = 4
    radial.description = 'Common full-envelope half-profile count; a multiple of four.'
    resolution = g.socket('Mesh Resolution', 'NodeSocketInt', default=1)
    resolution.min_value = 1
    resolution.max_value = 4
    exaggeration = g.socket('Height Exaggeration', 'NodeSocketFloat', default=10.)
    exaggeration.min_value = 1.
    exaggeration.max_value = 10.
    g.socket('Material', 'NodeSocketMaterial')
    g.socket('Geometry', 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Mouths', 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Plateau Boundary', 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    g.socket('Diagnostic Code', 'NodeSocketInt', 'OUTPUT')
    g.socket('Envelope Width', 'NodeSocketFloat', 'OUTPUT')
    inp = g.node('NodeGroupInput')
    carrier = inp.outputs['Carrier']

    g.section('Existing preparation retains circular corners and envelope profiles')
    prep = g.node('GeometryNodeGroup', 'Existing native mouths and circular corners')
    prep.node_tree = bpy.data.node_groups[prepare.NAME]
    g.bind(carrier, prep.inputs['Geometry'])
    prepared = V(g, prep.outputs['Geometry'])
    header = rm.split(g, prepared, 0)
    old_radial = rm.read(g, header, 'sampling_radial', 0)
    nv = V(g, inp.outputs['Radial Samples'])
    sampling_valid = g.math('GREATER_THAN', nv, 3.) * rm.equal(
        g, g.math('FLOORED_MODULO', nv, 4.), 0.)
    # The old sampler uses 3*nv/4 intervals per divided pavement member and
    # nv/2 across its separator; preserve those fractions on the new lattice.
    prepared = g.store(prepared, 'nv_base', named(g, 'nv_base', 'INT') * nv / old_radial,
                       'POINT', 'INT')
    prepared = g.store(prepared, 'sampling_radial', nv, 'POINT', 'INT')
    arms = rm.split(g, prepared, 1)
    envelope_width = prepare.stat(g, arms, named(g, 'width'))

    source_header = prepare.view(g, carrier, contract.HEADER)
    connectors = prepare.view(g, carrier, contract.CONNECTOR)
    members = prepare.view(g, carrier, contract.MEMBER)
    datum = rm.read(g, source_header, 's2_datum', 0)
    jp = g.separate(rm.read(g, source_header, 's2_junction_position', 0, 'FLOAT_VECTOR'))

    g.section('Unchanged profile-preserving sector and direct-quad center solve')
    surface = g.node('GeometryNodeGroup', 'Existing profile-preserving surface backend')
    if adaptive_half_profiles:
        from . import half_profile_backend_nodes
        surface.node_tree=half_profile_backend_nodes.build()
    else:surface.node_tree = bpy.data.node_groups[backend.NAME]
    g.bind(prepared, surface.inputs['Geometry'])
    for control in ('Mesh Resolution', 'Height Exaggeration', 'Material'):
        g.bind(inp.outputs[control], surface.inputs[control])
    surface.inputs['Grass'].default_value = False
    g.bind(datum, surface.inputs['Reference Elevation'])
    good_mesh, _minimum_cross, _all_quad = geometry_guard.check(g, surface.outputs['Geometry'])
    remove_strips = g.node('GeometryNodeDeleteGeometry', 'Complete Section paths own all approach strips')
    remove_strips.domain = 'FACE'
    remove_strips.mode = 'ALL'
    g.bind(surface.outputs['Geometry'], remove_strips.inputs['Geometry'])
    g.bind(g.math('GREATER_THAN', named(g, 'surface_part', 'INT'), 999.),
           remove_strips.inputs['Selection'])
    x, y, z = g.separate(g.position())
    positioned = g.setpos(remove_strips.outputs['Geometry'], g.xyz(x + jp[0], y + jp[1], z))

    # Export the exact sampled median-side boundary of a half-profile patch.
    # A future Bundle span consumer must reuse these vertices at the separator
    # seam. Interior crown edges and ordinary/full-envelope mouths are excluded.
    edge = g.node('GeometryNodeInputMeshEdgeVertices', 'Ends of a possible plateau boundary edge')
    incidence = g.node('GeometryNodeInputMeshEdgeNeighbors', 'Only exposed patch edges')
    plateau_ends = [prepare.sample(g, positioned, named(g, 'plateau_boundary', 'BOOLEAN'),
                                  edge.outputs['Vertex Index '+str(i)], 'BOOLEAN') for i in (1, 2)]
    boundary = g.node('GeometryNodeMeshToCurve', 'Exact sampled separator-side boundary')
    g.bind(positioned, boundary.inputs['Mesh'])
    g.bind(rm.equal(g, V(g, incidence.outputs['Face Count']), 1.) * plateau_ends[0] * plateau_ends[1],
           boundary.inputs['Selection'])

    g.section('A runtime mouth record for each actual directed Section endpoint')
    # All following fields evaluate on the MEMBER table.  Connector and arm
    # indices explicitly address their own tables; no one-member assumption.
    at = prepare.index(g)
    connector = named(g, 's2_connector_index', 'INT')
    member_start = rm.read(g, connectors, 's2_member_start', connector, 'INT')
    member_count = rm.read(g, connectors, 's2_member_count', connector, 'INT')
    divided = rm.equal(g, member_count, 2)
    tangent_v = rm.read(g, arms, 'tangent', connector, 'FLOAT_VECTOR')
    tangent = g.separate(tangent_v)
    cut_axis = tangent[:2]
    tilted = rm.read(g, arms, 'oblique', connector, 'BOOLEAN')
    right = (tangent[1], -tangent[0])
    station = rm.read(g, arms, 'inner_station', connector)
    rise = rm.read(g, arms, 'rise', connector)
    half_side = rm.read(g, arms, 'half_profile', connector, 'INT')
    half = g.math('GREATER_THAN', g.math('ABSOLUTE', half_side), 0.)

    def member_frame(member_index):
        endpoint_index = rm.read(g, members, 's2_endpoint_vertex', member_index, 'INT')
        endpoint = g.separate(prepare.sample(g, carrier, g.position(), endpoint_index, 'FLOAT_VECTOR'))
        edge = rm.read(g, members, 's2_endpoint_edge', member_index, 'INT')
        width = prepare.sample(g, carrier, named(g, 'width'), edge, domain='EDGE')
        leaving = rm.read(g, members, 's2_leaving', member_index, 'BOOLEAN')
        offset = prepare.sample(g, carrier, named(g, 'offset'), edge, domain='EDGE')
        outward_offset = offset * choose(g, leaving, 1., -1.)
        lateral = sum((endpoint[j] - jp[j]) * right[j] for j in (0, 1)) + outward_offset
        return endpoint, width, leaving, outward_offset, lateral

    endpoint, width, leaving, offset, lateral = member_frame(at)
    next_index = rm.read(g, members, 's2_next_vertex', at, 'INT')
    following = g.separate(prepare.sample(g, carrier, g.position(), next_index, 'FLOAT_VECTOR'))
    actual = oblique.unit(g, oblique.sub(following[:2], endpoint[:2]))
    tangent = oblique.select(g, tilted, actual, tangent[:2])
    tangent_v = g.xyz(*tangent)
    perpendicular = oblique.right(tangent)
    shear = oblique.sub(perpendicular, oblique.scale(tangent,
        oblique.dot(perpendicular, cut_axis) / oblique.dot(tangent, cut_axis)))
    mouth_lateral = oblique.select(g, tilted, shear, perpendicular)
    other = choose(g, rm.equal(g, at, member_start), member_start + member_count - 1., member_start, 'INT')
    _other_endpoint, _other_width, _other_leaving, _other_offset, other_lateral = member_frame(other)
    lower = g.math('LESS_THAN', lateral, other_lateral)
    # u follows the original Section direction, including reversed members.
    # The lower outward-right projection has its inner edge toward +right.
    inner_u = choose(g, divided,
        choose(g, lower, choose(g, leaving, 1., 0.), choose(g, leaving, 0., 1.)), .5)
    # half_side is in the outward connector frame. u follows the original
    # Section direction, so a tail endpoint reverses the inner-edge parameter.
    half_u = (1. + half_side * choose(g, leaving, 1., -1.)) * .5
    inner_u = choose(g, half, half_u, inner_u)
    legacy_trim = station - sum((endpoint[j] - jp[j]) * cut_axis[j] for j in (0, 1))
    trim = choose(g, tilted, legacy_trim / oblique.dot(tangent, cut_axis), legacy_trim)
    mouth = g.xyz(endpoint[0] + trim * tangent[0] + offset * mouth_lateral[0],
                  endpoint[1] + trim * tangent[1] + offset * mouth_lateral[1], jp[2])
    key = named(g, 'st_path_endpoint', 'INT')
    fields = {
        'st_mouth_key': (key, 'INT'),
        'st_mouth_position': (mouth, 'FLOAT_VECTOR'),
        'st_mouth_tangent': (tangent_v, 'FLOAT_VECTOR'),
        'st_mouth_lateral': (g.xyz(*mouth_lateral), 'FLOAT_VECTOR'),
        'st_mouth_cut_axis': (g.xyz(*cut_axis), 'FLOAT_VECTOR'),
        'st_mouth_oblique': (tilted, 'BOOLEAN'),
        'st_mouth_width': (width, 'FLOAT'),
        'st_mouth_rise': (rise, 'FLOAT'),
        'st_mouth_datum': (datum, 'FLOAT'),
        'st_mouth_nv': (nv, 'INT'),
        'st_mouth_trim': (trim, 'FLOAT'),
        'st_mouth_section_id': (named(g, 'st_path_section_id', 'INT'), 'INT'),
        'st_mouth_end': (named(g, 'st_path_end', 'INT'), 'INT'),
        'st_mouth_divided': (g.math('MAXIMUM', divided, half), 'BOOLEAN'),
        'st_mouth_half_profile': (half, 'BOOLEAN'),
        'st_mouth_inner_u': (inner_u, 'FLOAT'),
        'st_mouth_segments': (choose(g, half, nv, choose(g, divided, nv * .75, nv * 2.)), 'INT'),
    }
    if coupled:
        # A perpendicular full-width mouth can extend unnecessarily far along
        # the edge facing the shorter adjacent corner. Record only its actual
        # straight tail; the adaptive join may never move a circular arc.
        sectors = rm.split(g, prepared, 2)
        previous = g.math('FLOORED_MODULO', connector + rm.count(g, arms) - 1., rm.count(g, arms))
        left_arc = g.separate(rm.read(g, sectors, 'arc_start', connector, 'FLOAT_VECTOR'))
        right_arc = g.separate(rm.read(g, sectors, 'arc_end', previous, 'FLOAT_VECTOR'))
        fields['st_mouth_clearance_left'] = (station - sum(left_arc[j] * tangent[j] for j in (0, 1)), 'FLOAT')
        fields['st_mouth_clearance_right'] = (station - sum(right_arc[j] * tangent[j] for j in (0, 1)), 'FLOAT')
    mouths = prepare.rows(g, members, fields)
    mouths = g.setpos(mouths, g.xyz(named(g, 'st_mouth_key', 'INT'), 0., 0.))
    keys_valid = prepare.stat(g, mouths,
        g.math('GREATER_THAN', named(g, 'st_mouth_key', 'INT'), -1.), 'Min')
    member_counts_valid = prepare.stat(g, connectors,
        rm.equal(g, named(g, 's2_member_count', 'INT'), 1.) +
        rm.equal(g, named(g, 's2_member_count', 'INT'), 2.), 'Min')
    valid = V(g, prep.outputs['Valid']) * good_mesh * sampling_valid * member_counts_valid * keys_valid
    code = choose(g, prep.outputs['Valid'],
        choose(g, good_mesh,
            choose(g, sampling_valid * member_counts_valid * keys_valid, 0, 5, 'INT'), 4, 'INT'),
        prep.outputs['Diagnostic Code'], 'INT')

    def gate(geometry, label):
        switch = g.node('GeometryNodeSwitch', label)
        switch.input_type = 'GEOMETRY'
        g.bind(valid, switch.inputs['Switch'])
        g.bind(geometry, switch.inputs['True'])
        return switch.outputs['Output']

    out = g.node('NodeGroupOutput')
    g.bind(gate(positioned, 'Publish only a valid junction'), out.inputs['Geometry'])
    g.bind(gate(mouths, 'Publish actual member mouth frames'), out.inputs['Mouths'])
    g.bind(gate(boundary.outputs['Curve'], 'Publish the exact half-profile plateau boundary'),
           out.inputs['Plateau Boundary'])
    g.bind(valid, out.inputs['Valid'])
    g.bind(code, out.inputs['Diagnostic Code'])
    g.bind(envelope_width, out.inputs['Envelope Width'])
    g.g['construction'] = 'Existing round-corner direct-quads; actual member mouths; divided half-crown joins at a separator plateau'
    g.g['scope'] = ('Planar connectors; single or paired members with independent widths. '
                    'Nonparallel paired cuts require straight whole paths and compatible endpoint cuts in the network guard.')
    return g.g
